package dev.bridgey.android.connect

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.Base64

/**
 * protocol/test-vectors/connect-v1.json, generated by the Rust core: this phone derives the same pair
 * secret, pair check and tunnel transcript (the Mac checks the same file in ConnectVectorsTests).
 */
class ConnectVectorsTest {
    private val vectors = JSONObject(File(File(System.getProperty("bridgey.repoRoot") ?: "../.."), "protocol/test-vectors/connect-v1.json").readText())
    private val decoder = Base64.getDecoder()

    @Test fun pairSecretFromEitherSide() {
        val pair = vectors.getJSONObject("pair")
        val low = pair.getString("idLow")
        val high = pair.getString("idHigh")
        val cLow = decoder.decode(pair.getString("cLow"))
        val cHigh = decoder.decode(pair.getString("cHigh"))
        val expected = pair.getString("pairSecret")
        // The lower device computes it with its own contribution first, the higher one the other way round.
        assertEquals(expected, Base64.getEncoder().encodeToString(pairSecret(low, high, cLow, cHigh)))
        assertEquals(expected, Base64.getEncoder().encodeToString(pairSecret(high, low, cHigh, cLow)))
        assertEquals(pair.getString("pairCheckUrl"), pairCheck(decoder.decode(expected)))
        assertEquals(0, connectSide(low, high))
        assertEquals(1, connectSide(high, low))
    }

    @Test fun tunnelTranscriptBytes() {
        val t = vectors.getJSONObject("transcript")
        val bytes = tunnelTranscript(
            t.getString("sessionId"), t.getString("initiatorDeviceId"), t.getString("responderDeviceId"),
            t.getString("initiatorEphemeralKey"), t.getString("responderEphemeralKey"), t.getString("exporter"),
        )
        assertEquals(t.getString("bytes"), Base64.getEncoder().encodeToString(bytes))
    }

    @Test fun payloadsRoundTrip() {
        val contribution = ByteArray(32) { it.toByte() }
        val setup = decodeConnectSetup(connectSetupPayload(contribution, rotate = true))!!
        assertTrue(setup.contribution.contentEquals(contribution))
        assertTrue(setup.rotate)
        val addrs = listOf(ConnectAddress("192.168.1.20", "lan"), ConnectAddress("fd7a:115c:a1e0::5", "vpn", "tailscale"))
        val decoded = decodeConnectAddresses(connectAddressesPayload(42_458, addrs, "r_IQgYZ46wg"))!!
        assertEquals(ConnectAddresses(42_458, addrs, "r_IQgYZ46wg"), decoded)
    }

    @Test fun ipLiteralsNeverResolve() {
        listOf("10.0.0.1", "100.101.1.2", "2409:4040::1", "fd7a:115c:a1e0::1", "::ffff:192.168.1.2", "fe80::1").forEach { assertTrue(it, isUsableIpLiteral(it)) }
        listOf("localhost", "example.com", "127.0.0.1", "0.0.0.0", "::", "::1", "224.0.0.251", "ff02::1", "01.2.3.4", "1.2.3", "fe80::1%wlan0", "1::2::3")
            .forEach { assertFalse(it, isUsableIpLiteral(it)) }
    }

    @Test fun learnedAddressesExpire() {
        val now = 1_800_000_000_000L
        val list = listOf(LearnedAddress("10.0.0.2", 42_458, "lan", null, now - 1_000), LearnedAddress("10.0.0.3", 42_458, "lan", null, now - LEARNED_ADDRESS_TTL_MILLIS - 1))
        assertEquals(listOf(list[0]), decodeAddresses(encodeAddresses(list), now))
    }
}
